import json
import re
from rewards.pbebench import _parse_programs, reward

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

# Test on easy example to validate our approach
d = [x for x in demos if x['difficulty'] == 'easy' and x['cascade_length'] == 2 and x['success']][0]

def find_single_step(inp, out):
    """Find all (A, B) where input.replace(A, B) == output, 1<=len(A)<=3, 0<=len(B)<=3."""
    candidates = set()
    for la in range(1, 4):
        for start in range(len(inp) - la + 1):
            A = inp[start:start+la]
            lb = len(out) - len(inp) + la
            if 0 <= lb <= 3:
                B = out[start:start+lb]
                candidates.add((A, B))
    return candidates

# Find single-step for each pair
changed = [(i, inp, out) for i, (inp, out) in enumerate(zip(d['input_examples'], d['output_examples'])) if inp != out]
pair_candidates = {}
all_candidates = set()
for idx, inp, out in changed:
    cands = find_single_step(inp, out)
    pair_candidates[idx] = cands
    all_candidates.update(cands)

print(f"Changed pairs: {len(changed)}")
print(f"Unique single-step candidates: {len(all_candidates)}")

# Now try all sequences of length 1-5 from these candidates
def apply_seq(prog_seq, inp):
    s = inp
    for A, B in prog_seq:
        s = s.replace(A, B)
    return s

def score_seq(prog_seq):
    correct = 0
    for inp, out in zip(d['input_examples'], d['output_examples']):
        if apply_seq(prog_seq, inp) == out:
            correct += 1
    return correct / len(d['input_examples'])

# Try sequences
found = False
for k in range(1, 6):
    from itertools import permutations
    all_list = sorted(all_candidates)
    for combo_len in range(1, k+1):
        for combo in __import__('itertools').combinations(all_list, combo_len):
            for perm in permutations(combo):
                if score_seq(perm) == 1.0:
                    print(f"\nFound! k={k}, seq={perm}")
                    prog_str = ", ".join(f"\"replace('{A}', '{B}')\"" for A, B in perm)
                    print(f"Programs: [{prog_str}]")
                    found = True
                    break
            if found:
                break
        if found:
            break
    if found:
        break

