import json
import re
from collections import defaultdict
from itertools import combinations, permutations

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

# Let me test the complete approach on all demos
def solve_pbe(examples, max_programs=20):
    """
    Solve a PBE task from example pairs.

    Args:
        examples: list of (input_string, output_string)
        max_programs: maximum number of programs in the sequence

    Returns:
        dict with 'success' (bool), 'program' (list of program strings)
    """

    def apply_sequence(prog_seq, inp):
        """Apply a sequence of (A, B) programs to input string."""
        s = inp
        for A, B in prog_seq:
            s = s.replace(A, B)
        return s

    def evaluate(prog_seq):
        """Evaluate sequence against all examples. Returns (correct_count, score)."""
        correct = 0
        for inp, out in examples:
            if apply_sequence(prog_seq, inp) == out:
                correct += 1
        return correct, correct / len(examples)

    def is_valid(prog_seq):
        """Check length constraints."""
        if len(prog_seq) > max_programs:
            return False
        for A, B in prog_seq:
            if len(A) < 1 or len(A) > 3 or len(B) > 3:
                return False
        return True

    # Identify changed and unchanged pairs
    changed = [(i, inp, out) for i, (inp, out) in enumerate(examples) if inp != out]
    unchanged = [(i, inp, out) for i, (inp, out) in enumerate(examples) if inp == out]

    if not changed:
        return {"success": True, "program": [], "programs": []}

    # Generate single-step candidates
    single_candidates = set()
    pair_to_single = {}

    for idx, (inp, out) in changed:
        pair_cands = set()
        for la in range(1, 4):
            for start in range(len(inp) - la + 1):
                A = inp[start:start+la]
                lb = len(out) - len(inp) + la
                if 0 <= lb <= 3:
                    B = out[start:start+lb]
                    pair_cands.add((A, B))
        pair_to_single[idx] = pair_cands
        single_candidates.update(pair_cands)

    # Generate 2-step first-step candidates
    multi_candidates = set()
    for inp, out in changed:
        for la in range(1, 4):
            for start in range(len(inp) - la + 1):
                A1 = inp[start:start+la]
                for lb in range(4):
                    B1 = out[start:start+lb]
                    intermediate = inp.replace(A1, B1)
                    if intermediate != inp and intermediate != out:
                        # Check if intermediate can reach out in one step
                        for la2 in range(1, 4):
                            for start2 in range(len(intermediate) - la2 + 1):
                                A2 = intermediate[start2:start2+la2]
                                lb2 = len(out) - len(intermediate) + la2
                                if 0 <= lb2 <= 3:
                                    B2 = out[start2:start2+lb2]
                                    if intermediate.replace(A2, B2) == out:
                                        multi_candidates.add((A1, B1))
                                        break
                                if lb2 > 0:
                                    break
                            else:
                                continue
                            break

    all_candidates = single_candidates | multi_candidates

    # Filter by safety: must not incorrectly modify unchanged examples
    def is_safe(prog):
        A, B = prog
        for _, inp, out in unchanged:
            if inp.replace(A, B) != out:
                return False
        return True

    safe_candidates = [prog for prog in all_candidates if is_safe(prog)]

    # Sort by usefulness: number of changed pairs it solves directly
    def usefulness(prog):
        A, B = prog
        count = 0
        for _, inp, out in changed:
            if inp.replace(A, B) == out:
                count += 1
        return count

    safe_candidates.sort(key=usefulness, reverse=True)

    # Search for valid sequence using iterative deepening + DFS
    best_result = {"success": False, "program": [], "programs": []}
    best_score = 0.0
    found_all = False

    # Try sequences of increasing length
    for seq_len in range(1, max_programs + 1):
        if found_all:
            break

        def search(current_seq, depth):
            nonlocal best_result, best_score, found_all

            correct, score = evaluate(current_seq)

            if score >= best_score and (not best_result["success"] or len(current_seq) < len(best_result.get("programs", []))):
                if correct == len(examples):
                    best_result = {
                        "success": True,
                        "program": [f"replace('{A}', '{B}')" for A, B in current_seq],
                        "programs": list(current_seq),
                    }
                    found_all = True
                else:
                    best_score = score
                    if not best_result["success"] or len(current_seq) < len(best_result.get("programs", [])):
                        best_result = {
                            "success": False,
                            "program": [f"replace('{A}', '{B}')" for A, B in current_seq],
                            "programs": list(current_seq),
                            "score": score,
                        }

            if found_all or depth >= seq_len:
                return

            # Generate candidates from unsolved pairs
            candidates = set()
            for i, (inp, out) in enumerate(examples):
                if apply_sequence(current_seq, inp) == out:
                    continue
                current = apply_sequence(current_seq, inp)
                for la in range(1, 4):
                    for start in range(len(current) - la + 1):
                        A = current[start:start+la]
                        lb = len(out) - len(current) + la
                        if 0 <= lb <= 3:
                            B = out[start:start+lb]
                            candidates.add((A, B))

            # Also add safe multi-step candidates
            candidates.update(safe_candidates)

            # Filter by safety
            filtered = []
            for prog in candidates:
                A, B = prog
                test_seq = current_seq + [prog]
                safe = True
                for _, uinp, uout in unchanged:
                    if apply_sequence(test_seq, uinp) != uout:
                        safe = False
                        break
                if safe:
                    filtered.append(prog)

            # Sort by immediate improvement
            def immediate_improvement(prog):
                A, B = prog
                improved = 0
                for inp, out in changed:
                    if apply_sequence(current_seq, inp) != out:
                        if apply_sequence(current_seq + [prog], inp) == out:
                            improved += 1
                return improved

            filtered.sort(key=immediate_improvement, reverse=True)

            # Try top candidates (limit branching)
            for prog in filtered[:20]:
                search(current_seq + [prog], depth + 1)
                if found_all:
                    return

        search([], 0)

    return best_result


# Test on all demos
results = {"correct": 0, "total": len(demos), "details": []}
for i, d in enumerate(demos):
    examples = list(zip(d['input_examples'], d['output_examples']))
    max_prog = 20 if d['difficulty'] == 'hard' else 5

    try:
        result = solve_pbe(examples, max_programs=max_prog)
        is_correct = result["success"] and result["program"] is not None
        if is_correct:
            # Verify with the actual verifier
            entry = {"inputs": d['input_examples'], "outputs": d['output_examples']}
            prog_str = "\n".join(result["program"]) if result["program"] else ""
            vresult = reward(prog_str, True, entry, max_programs=max_prog)
            is_correct = vresult.get("value", 0) == 1.0

        if is_correct:
            results["correct"] += 1
        results["details"].append({
            "demo": i,
            "success": d['success'],
            "our_success": is_correct,
            "programs": len(result.get("programs", [])),
            "score": result.get("score", 0),
        })

        if not is_correct:
            print(f"Demo {i}: FAILED (our={is_correct}, expected={d['success']})")
            changed = [(a,b) for a,b in zip(d['input_examples'], d['output_examples']) if a != b]
            print(f"  Changed: {len(changed)}/50")
            for a, b in changed[:5]:
                print(f"    '{a}' -> '{b}'")
            print(f"  Programs found: {result.get('programs', [])}")
            if results["correct"] >= 3:
                break
    except Exception as e:
        print(f"Demo {i}: ERROR: {e}")
        results["details"].append({
            "demo": i,
            "success": d['success'],
            "our_success": False,
            "error": str(e),
        })

print(f"\nResults: {results['correct']}/{results['total']} correct")

