# Simpler, more efficient approach
def solve_pbe(examples, max_programs=20):
    """
    Solve a PBE task using greedy program discovery.
    """
    def apply_seq(prog_seq, inp):
        s = inp
        for A, B in prog_seq:
            s = s.replace(A, B)
        return s

    # Identify changed and unchanged pairs
