    if not changed:
        return {"success": True, "program": [], "programs": []}

    # Safety filter
    def is_safe(prog, prog_seq):
        A, B = prog
        test_seq = prog_seq + [prog]
        for _, uinp, uout in unchanged:
            if apply_seq(test_seq, uinp) != uout:
                return False
        return True

    # Generate candidate programs
    def generate_candidates(prog_seq):
        candidates = set()
        # Generate from unsolved pairs
        for _, inp, out in changed:
            current = apply_seq(prog_seq, inp)
            if current == out:
                continue
            for la in range(1, 4):
                for start in range(len(current) - la + 1):
                    A = current[start:start+la]
                    lb = len(out) - len(current) + la
                    if 0 <= lb <= 3:
                        B = out[start:start+lb]
                        candidates.add((A, B))
        return candidates

    # Greedy search
    prog_seq = []
    for _ in range(max_programs):
        candidates = generate_candidates(prog_seq)

        if not candidates:
            break

        # Filter safe candidates
        safe = [c for c in candidates if is_safe(c, prog_seq)]

        if not safe:
            break

        # Score each candidate by number of remaining pairs it would solve
        def score(prog):
            A, B = prog
            solved = 0
            for _, inp, out in changed:
                if apply_seq(prog_seq, inp) != out:
                    if apply_seq(prog_seq + [prog], inp) == out:
                        solved += 1
            return solved

        # Also consider how much each candidate improves overall
        def full_score(prog):
            A, B = prog
            new_seq = prog_seq + [prog]
            correct = 0
            for inp, out in examples:
                if apply_seq(new_seq, inp) == out:
                    correct += 1
            return correct / len(examples)

