import json
import re
from collections import defaultdict
from rewards.pbebench import _parse_programs, reward

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

def solve_pbe(examples, max_programs=20, time_limit_seconds=30):
    """
    Solve a PBE task from example pairs.

    Strategy:
    1. Generate single-step and multi-step candidate programs
    2. Greedily select programs that maximize correct examples
    3. Use iterative deepening with limited backtracking

    Returns dict with 'success', 'program', 'programs', 'score'
    """
    import time
    start_time = time.time()

    def apply_seq(prog_seq, inp):
        s = inp
        for A, B in prog_seq:
            s = s.replace(A, B)
        return s

    def evaluate(prog_seq):
        correct = 0
        for inp, out in examples:
            if apply_seq(prog_seq, inp) == out:
                correct += 1
        return correct, correct / len(examples)

    # Identify changed and unchanged pairs
    changed = [(i, inp, out) for i, (inp, out) in enumerate(examples) if inp != out]
    unchanged = [(i, inp, out) for i, (inp, out) in enumerate(examples) if inp == out]

    if not changed:
        return {"success": True, "program": [], "programs": []}

    def is_safe(prog, prog_seq):
        """Check if adding prog to prog_seq breaks any unchanged pair."""
        A, B = prog
        test_seq = prog_seq + [prog]
        for _, uinp, uout in unchanged:
            if apply_seq(test_seq, uinp) != uout:
                return False
        return True

    def generate_single_step_candidates(prog_seq):
        """Generate single-step candidates from unsolved pairs."""
        candidates = set()
        for _, inp, out in changed:
            current = apply_seq(prog_seq, inp)
            if current == out:
                continue
            for la in range(1, 4):
                for start in range(len(current) - la + 1):
                    A = current[start:start+la]
                    lb = len(out) - len(current) + la
                    if 0 <= lb <= 3:
                        B = out[start:start+lb]
                        candidates.add((A, B))
        return candidates

    def generate_multi_step_candidates(prog_seq):
        """Generate multi-step (2-step) first-step candidates."""
        candidates = set()
        for _, inp, out in changed:
            current = apply_seq(prog_seq, inp)
            if current == out:
                continue
            for la in range(1, 4):
                for start in range(len(current) - la + 1):
                    A1 = current[start:start+la]
                    for lb in range(4):
                        B1 = out[start:start+lb]
                        intermediate = current.replace(A1, B1)
                        if intermediate != current and intermediate != out:
                            # Check if intermediate can reach out in one step
                            for la2 in range(1, 4):
                                found = False
                                for start2 in range(len(intermediate) - la2 + 1):
                                    A2 = intermediate[start2:start2+la2]
                                    lb2 = len(out) - len(intermediate) + la2
                                    if 0 <= lb2 <= 3:
                                        B2 = out[start2:start2+lb2]
                                        if intermediate.replace(A2, B2) == out:
                                            candidates.add((A1, B1))
                                            found = True
                                            break
                                if found:
                                    break
        return candidates

    def get_candidates(prog_seq):
        """Get all safe candidates from current state."""
        single = generate_single_step_candidates(prog_seq)
        multi = generate_multi_step_candidates(prog_seq)
        all_cands = single | multi

        safe = [p for p in all_cands if is_safe(p, prog_seq)]
        return safe

    def score_program(prog, prog_seq):
        """Score a program by how many total pairs it gets correct."""
        A, B = prog
        new_seq = prog_seq + [prog]
        correct = sum(1 for inp, out in examples if apply_seq(new_seq, inp) == out)
        return correct

    def improve_program(prog, prog_seq):
        """Score by how many additional pairs it solves."""
        A, B = prog
        new_seq = prog_seq + [prog]
        before = sum(1 for _, i, o in changed if apply_seq(prog_seq, i) != o)
        after = sum(1 for _, i, o in changed if apply_seq(new_seq, i) != o)
        return before - after  # How many pairs it solves

    # Phase 1: Greedy program selection
    best_result = {"success": False, "program": [], "programs": [], "score": 0.0}

    prog_seq = []
    max_iterations = max_programs

    for iteration in range(max_iterations):
        if time.time() - start_time > time_limit_seconds:
            break

        correct, score = evaluate(prog_seq)
        if correct == len(examples):
            best_result = {
                "success": True,
                "program": [f"replace('{A}', '{B}')" for A, B in prog_seq],
                "programs": list(prog_seq),
                "score": 1.0,
            }
            break

        if score > best_result.get("score", 0):
            best_result = {
                "success": False,
                "program": [f"replace('{A}', '{B}')" for A, B in prog_seq],
                "programs": list(prog_seq),
                "score": score,
            }

        candidates = get_candidates(prog_seq)
        if not candidates:
            break

        # Sort by improvement score
        candidates.sort(key=lambda p: improve_program(p, prog_seq), reverse=True)

        # Try the best program that improves the score
        found = False
        for prog in candidates:
            if improve_program(prog, prog_seq) > 0:
                prog_seq = prog_seq + [prog]
                found = True
                break

        if not found:
            # No program improves, but try the one that scores highest overall
            candidates.sort(key=lambda p: score_program(p, prog_seq), reverse=True)
            if score_program(candidates[0], prog_seq) > score:
                prog_seq = prog_seq + [candidates[0]]
                found = True

        if not found:
            # Stuck - break and return best so far
            break

    # If we didn't find a perfect solution, try limited backtracking
    if not best_result.get("success", False):
        # Try adding a program that we might have missed
        # Generate candidates with longer multi-step analysis
        prog_seq2 = list(prog_seq)

        for _ in range(max_programs - len(prog_seq2)):
            correct, score = evaluate(prog_seq2)
            if correct == len(examples):
                best_result = {
                    "success": True,
                    "program": [f"replace('{A}', '{B}')" for A, B in prog_seq2],
                    "programs": list(prog_seq2),
                    "score": 1.0,
                }
                break

            candidates = get_candidates(prog_seq2)
            if not candidates:
                break

            candidates.sort(key=lambda p: score_program(p, prog_seq2), reverse=True)
            prog_seq2 = prog_seq2 + [candidates[0]]

        if not best_result.get("success", False):
            correct, score = evaluate(prog_seq2)
            best_result = {
                "success": score >= 0.95,
                "program": [f"replace('{A}', '{B}')" for A, B in prog_seq2],
                "programs": list(prog_seq2),
                "score": score,
            }

    return best_result


# Test on all 100 demos
results = {"correct": 0, "total": len(demos), "failures": []}
for i, d in enumerate(demos):
    examples = list(zip(d['input_examples'], d['output_examples']))
    max_prog = 20 if d['difficulty'] == 'hard' else 5

    try:
        result = solve_pbe(examples, max_programs=max_prog, time_limit_seconds=10)
        is_correct = result["success"]

        if is_correct:
            # Verify with the actual verifier
            entry = {"inputs": d['input_examples'], "outputs": d['output_examples']}
            prog_str = "\n".join(result["program"]) if result["program"] else "[]"
            vresult = reward(prog_str, True, entry, max_programs=max_prog)
            is_correct = vresult.get("value", 0) == 1.0

        if is_correct:
            results["correct"] += 1
        else:
            results["failures"].append(i)

        status = "✓" if is_correct else "✗"
        print(f"Demo {i}: {status} ({d['difficulty']}, expected={d['success']}, programs={len(result.get('programs', []))}, score={result.get('score', 0):.2f})")

        if results["correct"] % 20 == 0:
            print(f"  Progress: {results['correct']}/{i+1} correct so far")

    except Exception as e:
        import traceback
        traceback.print_exc()
        results["failures"].append(i)
        print(f"Demo {i}: ERROR: {e}")

print(f"\nFinal Results: {results['correct']}/{results['total']} correct")
print(f"Failed demos: {results['failures']}")

