import json
import re
from collections import defaultdict
from rewards.pbebench import _parse_programs, reward

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

def solve_pbe(examples, max_programs=20, time_limit_seconds=30):
    """
    Solve a PBE task from example pairs using greedy + limited backtracking.
    """
    import time
    start_time = time.time()

    def apply_seq(prog_seq, inp):
        s = inp
        for A, B in prog_seq:
            s = s.replace(A, B)
        return s

    def evaluate(prog_seq):
        correct = 0
        for inp, out in examples:
            if apply_seq(prog_seq, inp) == out:
                correct += 1
        return correct, correct / len(examples)

    changed = [(i, inp, out) for i, (inp, out) in enumerate(examples) if inp != out]
    unchanged = [(i, inp, out) for i, (inp, out) in enumerate(examples) if inp == out]

    if not changed:
        return {"success": True, "program": [], "programs": []}

    def is_safe(prog, prog_seq):
        A, B = prog
        test_seq = prog_seq + [prog]
        for _, uinp, uout in unchanged:
            if apply_seq(test_seq, uinp) != uout:
                return False
        return True

    def get_output_substrings(out):
        """Get all substrings of output of length 0-3."""
        subs = set()
        for lb in range(4):
            for start in range(len(out) - lb + 1):
                subs.add(out[start:start+lb])
        return subs

    def generate_single_step(prog_seq):
        """Generate single-step candidates from unsolved pairs."""
        candidates = set()
        for _, inp, out in changed:
            current = apply_seq(prog_seq, inp)
            if current == out:
                continue
            for la in range(1, 4):
                for start in range(len(current) - la + 1):
                    A = current[start:start+la]
                    lb = len(out) - len(current) + la
                    if 0 <= lb <= 3:
                        B = out[start:start+lb]
                        candidates.add((A, B))
        return candidates

    def generate_multi_step(prog_seq):
        """Generate 2-step first-step candidates using output substrings."""
        candidates = set()
        for _, inp, out in changed:
            current = apply_seq(prog_seq, inp)
            if current == out:
                continue

            output_subs = get_output_substrings(out)

            for la in range(1, 4):
                for start in range(len(current) - la + 1):
                    A1 = current[start:start+la]
                    for B1 in output_subs:
                        intermediate = current.replace(A1, B1)
                        if intermediate != current and intermediate != out:
                            for la2 in range(1, 4):
                                found = False
                                for start2 in range(len(intermediate) - la2 + 1):
                                    A2 = intermediate[start2:start2+la2]
                                    lb2 = len(out) - len(intermediate) + la2
                                    if 0 <= lb2 <= 3:
                                        B2 = out[start2:start2+lb2]
                                        if intermediate.replace(A2, B2) == out:
                                            candidates.add((A1, B1))
                                            found = True
                                            break
                                if found:
                                    break

        return candidates

    def get_candidates(prog_seq):
        single = generate_single_step(prog_seq)
        multi = generate_multi_step(prog_seq)
        all_cands = single | multi
        return [p for p in all_cands if is_safe(p, prog_seq)]

    def improve(prog, prog_seq):
        new_seq = prog_seq + [prog]
        before_solved = sum(1 for _, i, o in changed if apply_seq(prog_seq, i) == o)
        after_solved = sum(1 for _, i, o in changed if apply_seq(new_seq, i) == o)
        return after_solved - before_solved

    def total_score(prog, prog_seq):
        new_seq = prog_seq + [prog]
        return sum(1 for inp, out in examples if apply_seq(new_seq, inp) == out)

    best_result = {"success": False, "program": [], "programs": [], "score": 0.0}
    prog_seq = []

    for iteration in range(max_programs):
        if time.time() - start_time > time_limit_seconds:
            break

        correct, score = evaluate(prog_seq)
        if correct == len(examples):
            return {
                "success": True,
                "program": [f"replace('{A}', '{B}')" for A, B in prog_seq],
                "programs": list(prog_seq),
                "score": 1.0,
            }

        if score > best_result.get("score", 0):
            best_result = {
                "success": False,
                "program": [f"replace('{A}', '{B}')" for A, B in prog_seq],
                "programs": list(prog_seq),
                "score": score,
            }

        candidates = get_candidates(prog_seq)
        if not candidates:
            break

        # Sort by improvement, then by total score
        candidates.sort(key=lambda p: (improve(p, prog_seq), total_score(p, prog_seq)), reverse=True)

        found = False
        for prog in candidates:
            if improve(prog, prog_seq) > 0:
                prog_seq = prog_seq + [prog]
                found = True
                break

        if not found and candidates:
            # Take the one with highest total score
            prog_seq = prog_seq + [candidates[0]]
            found = True

        if not found:
            break

    # Final evaluation
    correct, score = evaluate(prog_seq)
    if correct == len(examples):
        return {
            "success": True,
            "program": [f"replace('{A}', '{B}')" for A, B in prog_seq],
            "programs": list(prog_seq),
            "score": 1.0,
        }

    return {
        "success": False,
        "program": [f"replace('{A}', '{B}')" for A, B in prog_seq],
        "programs": list(prog_seq),
        "score": score,
    }


# Test on first 30 demos
results = {"correct": 0, "total": min(30, len(demos)), "failures": []}
for i, d in enumerate(demos[:30]):
    examples = list(zip(d['input_examples'], d['output_examples']))
    max_prog = 20 if d['difficulty'] == 'hard' else 5

    try:
        result = solve_pbe(examples, max_programs=max_prog, time_limit_seconds=10)
        is_correct = result["success"]
        if is_correct:
            entry = {"inputs": d['input_examples'], "outputs": d['output_examples']}
            prog_str = "\n".join(result["program"]) if result["program"] else "[]"
            vresult = reward(prog_str, True, entry, max_programs=max_prog)
            is_correct = vresult.get("value", 0) == 1.0

        status = "✓" if is_correct else "✗"
        print(f"Demo {i}: {status} ({d['difficulty']}, programs={len(result.get('programs', []))}, score={result.get('score', 0):.2f})")

        if is_correct:
            results["correct"] += 1
        else:
            results["failures"].append(i)
    except Exception as e:
        import traceback
        traceback.print_exc()
        results["failures"].append(i)

print(f"\nResults: {results['correct']}/{results['total']} correct")
print(f"Failures: {results['failures']}")

